-- LUMINAC21 x STEALTHGRADE / Supabase schema. Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null check(char_length(title) between 2 and 120),summary text not null check(char_length(summary) between 5 and 500),body_md text not null default '',category text not null default 'Engineering',status text not null default 'draft' check(status in('draft','published','archived')),featured boolean not null default false,repository_url text,demo_url text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.research_articles(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null check(char_length(title) between 2 and 160),excerpt text not null check(char_length(excerpt) between 5 and 600),body_md text not null default '',category text not null default 'Research',status text not null default 'draft' check(status in('draft','published','archived')),reading_minutes integer not null default 1 check(reading_minutes between 1 and 240),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.technologies(id uuid primary key default gen_random_uuid(),name text not null unique,category text not null,usage_note text not null default '',sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.activity_logs(id uuid primary key default gen_random_uuid(),title text not null,details text not null default '',activity_type text not null default 'update',related_project_id uuid references public.projects(id) on delete set null,occurred_at timestamptz not null default now(),visibility text not null default 'public' check(visibility in('public','private')),created_at timestamptz not null default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),sender_name text not null check(char_length(sender_name) between 2 and 80),sender_email text not null check(char_length(sender_email) between 5 and 254),subject text not null check(char_length(subject) between 3 and 120),message text not null check(char_length(message) between 10 and 5000),created_at timestamptz not null default now(),is_read boolean not null default false);
create index if not exists projects_public_idx on public.projects(status,featured,published_at desc);
create index if not exists research_public_idx on public.research_articles(status,published_at desc);
create index if not exists activity_public_idx on public.activity_logs(visibility,occurred_at desc);
create index if not exists contact_created_idx on public.contact_messages(created_at desc);
drop trigger if exists projects_updated_at on public.projects; create trigger projects_updated_at before update on public.projects for each row execute function public.set_updated_at();
drop trigger if exists research_updated_at on public.research_articles; create trigger research_updated_at before update on public.research_articles for each row execute function public.set_updated_at();
alter table public.projects enable row level security; alter table public.research_articles enable row level security; alter table public.technologies enable row level security; alter table public.activity_logs enable row level security; alter table public.contact_messages enable row level security;
drop policy if exists projects_public_read on public.projects; create policy projects_public_read on public.projects for select to anon,authenticated using(status='published');
drop policy if exists projects_admin_all on public.projects; create policy projects_admin_all on public.projects for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists research_public_read on public.research_articles; create policy research_public_read on public.research_articles for select to anon,authenticated using(status='published');
drop policy if exists research_admin_all on public.research_articles; create policy research_admin_all on public.research_articles for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists technologies_public_read on public.technologies; create policy technologies_public_read on public.technologies for select to anon,authenticated using(true);
drop policy if exists technologies_admin_all on public.technologies; create policy technologies_admin_all on public.technologies for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists activity_public_read on public.activity_logs; create policy activity_public_read on public.activity_logs for select to anon,authenticated using(visibility='public');
drop policy if exists activity_admin_all on public.activity_logs; create policy activity_admin_all on public.activity_logs for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists contact_public_insert on public.contact_messages; create policy contact_public_insert on public.contact_messages for insert to anon,authenticated with check(is_read=false and char_length(sender_name) between 2 and 80 and char_length(sender_email) between 5 and 254 and char_length(subject) between 3 and 120 and char_length(message) between 10 and 5000);
drop policy if exists contact_admin_all on public.contact_messages; create policy contact_admin_all on public.contact_messages for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
grant select on public.projects,public.research_articles,public.technologies,public.activity_logs to anon,authenticated; grant insert on public.contact_messages to anon,authenticated; grant all on public.projects,public.research_articles,public.technologies,public.activity_logs,public.contact_messages to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('site-media','site-media',true,5242880,array['image/jpeg','image/png','image/webp','image/avif','image/svg+xml']) on conflict(id) do nothing;
drop policy if exists site_media_public_read on storage.objects; create policy site_media_public_read on storage.objects for select using(bucket_id='site-media');
drop policy if exists site_media_admin_insert on storage.objects; create policy site_media_admin_insert on storage.objects for insert to authenticated with check(bucket_id='site-media' and (auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists site_media_admin_update on storage.objects; create policy site_media_admin_update on storage.objects for update to authenticated using(bucket_id='site-media' and (auth.jwt()->'app_metadata'->>'role')='admin') with check(bucket_id='site-media' and (auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists site_media_admin_delete on storage.objects; create policy site_media_admin_delete on storage.objects for delete to authenticated using(bucket_id='site-media' and (auth.jwt()->'app_metadata'->>'role')='admin');
